import {notFound} from "next/navigation";import {Footer} from "@/components/Footer";import {Header} from "@/components/Header";import {InquiryForm} from "@/components/InquiryForm";import {getDealer,getVehicle} from "@/lib/api";
const money=(v:string)=>new Intl.NumberFormat("en-NG",{style:"currency",currency:"NGN",maximumFractionDigits:0}).format(Number(v));
export default async function Detail({params}:{params:Promise<{slug:string}>}){const {slug}=await params;try{const [dealer,vehicle]=await Promise.all([getDealer(),getVehicle(slug)]);return <><Header dealer={dealer}/><main id="main" style={{"--brand":dealer.primary_color} as React.CSSProperties}><section className="detailTop"><div className="gallery">{vehicle.images.length?vehicle.images.map(i=><img key={i.id} src={i.url} alt={i.alt_text}/>):<div className="placeholder large">{vehicle.make[0]}</div>}</div><aside className="summary"><span className={`status ${vehicle.availability}`}>{vehicle.availability}</span><span className="eyebrow">{vehicle.year} · {vehicle.condition}</span><h1>{vehicle.make}<br/><em>{vehicle.model}</em></h1><div className="price">{money(vehicle.price)}</div><p>Asking price. An offer starts a conversation and does not complete a sale.</p><dl><div><dt>Mileage</dt><dd>{vehicle.mileage_km.toLocaleString()} km</dd></div><div><dt>Transmission</dt><dd>{vehicle.transmission}</dd></div><div><dt>Fuel</dt><dd>{vehicle.fuel_type}</dd></div><div><dt>Location</dt><dd>{vehicle.location}</dd></div></dl></aside></section><section className="detailContent"><div><span className="eyebrow">Dealer-provided overview</span><h2>The full picture.</h2><p>{vehicle.description}</p></div><div><h3>Notable features</h3><ul>{vehicle.features.map(f=><li key={f}>{f}</li>)}</ul><h3>Known issues</h3><p>{vehicle.known_issues||"The dealer has not listed known issues."}</p><h3>Seller-provided history</h3><p>{vehicle.seller_history||"No seller history supplied."}</p></div></section><section className="requestSection"><div><span className="eyebrow">Start a conversation</span><h2>{vehicle.availability==="sold"?"Looking for something similar?":"See it for yourself."}</h2><p>This form does not reserve or purchase the vehicle.</p></div><InquiryForm slug={slug} sold={vehicle.availability==="sold"}/></section></main><Footer dealer={dealer}/></>}catch{return notFound()}}
